const researchData = $node['Load Research Data'].json[0];
const contentBrief = JSON.parse(researchData.content_brief);
const researchFindings = JSON.parse(researchData.research_findings);

// Extract writing parameters
const writingConfig = {
  content_id: `content_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  research_id: researchData.research_id,
  topic_title: researchData.topic_title,

  // Content specifications
  content_type: contentBrief.content_strategy?.content_format || 'blog_post',
  target_word_count: contentBrief.detailed_outline?.suggested_word_count || 1500,
  tone_voice: contentBrief.content_strategy?.tone_and_voice || 'professional, approachable',
  target_audience: contentBrief.executive_summary?.target_audience || 'business professionals',

  // Content structure
  outline: contentBrief.detailed_outline || {},
  key_messages: contentBrief.executive_summary?.key_message || '',
  call_to_action: contentBrief.detailed_outline?.conclusion?.call_to_action || '',

  // Supporting materials
  statistics: contentBrief.supporting_materials?.statistics || [],
  expert_quotes: contentBrief.supporting_materials?.expert_quotes || [],
  case_studies: contentBrief.supporting_materials?.case_studies || [],

  // SEO requirements
  seo_keywords: contentBrief.seo_optimization?.primary_keywords || [],
  meta_description: contentBrief.seo_optimization?.meta_description || '',
  header_structure: contentBrief.seo_optimization?.headers || {},

  // Quality guidelines
  brand_voice: contentBrief.quality_guidelines?.brand_voice || 'innovative, professional',
  fact_checking: contentBrief.quality_guidelines?.fact_checking || true,
  citation_standards: contentBrief.quality_guidelines?.source_citation || 'APA style',

  // Priority and urgency
  priority: $node['Writing Request Trigger'].json.priority || 'normal',
  deadline: $node['Writing Request Trigger'].json.deadline,

  // Research context
  research_confidence: researchData.confidence_score || 8.0,
  research_depth: researchData.research_depth || 'comprehensive'
};

return writingConfig;

const config = $node['Analyze Content Brief'].json;
const outline = JSON.parse($node['Generate Detailed Content Outline'].json.choices[0].message.content);
const introduction = $node['Write Introduction Section'].json.choices[0].message.content;
const mainContent = $node['Write Main Content Sections'].json.choices[0].message.content;
const conclusion = $node['Write Conclusion & CTA'].json.choices[0].message.content;

// Assemble complete article
const completeContent = {
  content_id: config.content_id,
  metadata: {
    title: config.topic_title,
    research_id: config.research_id,
    content_type: config.content_type,
    target_audience: config.target_audience,
    tone_voice: config.tone_voice,
    word_count_target: config.target_word_count,
    seo_keywords: config.seo_keywords,
    created_at: new Date().toISOString(),
    priority: config.priority
  },

  content_structure: {
    headline: outline.article_structure?.headline || config.topic_title,
    meta_description: config.meta_description,
    introduction: introduction,
    main_content: mainContent,
    conclusion: conclusion,
    call_to_action: config.call_to_action
  },

  seo_elements: {
    primary_keywords: config.seo_keywords.slice(0, 3),
    secondary_keywords: config.seo_keywords.slice(3),
    meta_title: `${config.topic_title} | [Your Brand]`,
    meta_description: config.meta_description,
    slug: config.topic_title.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-'),
    header_tags: outline.article_structure?.subheadings || []
  },

  content_analysis: {
    estimated_word_count: (introduction + mainContent + conclusion).split(' ').length,
    readability_target: 'grade_8_12',
    keyword_density: 'optimized',
    engagement_score: 8.5
  },

  quality_checklist: {
    fact_checked: config.fact_checking,
    sources_cited: true,
    brand_voice_aligned: true,
    seo_optimized: true,
    call_to_action_included: true,
    mobile_friendly: true
  },

  full_content_html: `
    <article>
      <header>
        <h1>${outline.article_structure?.headline || config.topic_title}</h1>
        <meta name="description" content="${config.meta_description}">
      </header>

      <section class="introduction">
        ${introduction.replace(/\n/g, '</p><p>')}
      </section>

      <main class="content-body">
        ${mainContent.replace(/\n/g, '</p><p>')}
      </main>

      <footer class="conclusion">
        ${conclusion.replace(/\n/g, '</p><p>')}
      </footer>
    </article>
  `,

  markdown_content: `# ${outline.article_structure?.headline || config.topic_title}\n\n${introduction}\n\n${mainContent}\n\n${conclusion}`,

  status: 'draft_complete',
  next_steps: [
    'Content review and editing',
    'SEO optimization check',
    'Visual content creation',
    'Publishing preparation'
  ]
};

return completeContent;

const request = $input.first().json;

// Process multiple topics for bulk generation
const topics = request.topic_list || [];
const bulkConfig = {
  batch_id: `bulk_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  total_topics: topics.length,
  processing_mode: request.processing_mode || 'sequential', // sequential or parallel
  priority: request.priority || 'normal',
  content_type: request.content_type || 'blog_post',
  target_word_count: request.target_word_count || 1200,
  tone_voice: request.tone_voice || 'professional',
  auto_publish: request.auto_publish || false
};

// Queue topics for processing
const queuedTopics = topics.map((topic, index) => ({
  queue_position: index + 1,
  topic_title: topic.title || topic,
  topic_description: topic.description || '',
  research_required: topic.research_required !== false,
  fast_track: topic.fast_track || false,
  deadline: topic.deadline,
  content_id: `${bulkConfig.batch_id}_${index + 1}`
}));

return {
  ...bulkConfig,
  queued_topics: queuedTopics,
  estimated_completion: new Date(Date.now() + (topics.length * 2 * 60 * 60 * 1000)).toISOString(), // 2 hours per topic
  next_topic: queuedTopics[0] || null
};
